def solve(grid):
    """Count islands in a binary grid (batch 2).

    An island is a group of horizontally or vertically adjacent cells containing 1.
    """
    if not grid:
        return 0
    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def dfs(i, j):
        stack = [(i, j)]
        visited[i][j] = True
        while stack:
            x, y = stack.pop()
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny] == 1:
                    visited[nx][ny] = True
                    stack.append((nx, ny))

    count = 0
    for i in range(m):
        for j in range(n):
