def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Handles non-list or non-integer inputs gracefully by returning 0.
    """
    # Validate input is iterable of integers
    if not isinstance(nums, (list, tuple)):
        return 0
    # Convert elements to ints when possible, ignore others
    cleaned = []
    for x in nums:
        try:
            cleaned.append(int(x))
        except Exception:
            # Non-convertible element, skip it
            continue
    if not cleaned:
        return 0
    import bisect
    tails = []
    for x in cleaned:
        # Find insertion point for strict increase
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

