def solve(matrix):
    """Return elements of a rectangular matrix in clockwise spiral order.
    Handles empty matrix or matrix with empty rows gracefully.
    """
    if not matrix or not any(matrix):
        return []
    # Determine effective dimensions; assume rectangular but guard against jagged rows
    rows = len(matrix)
    cols = max(len(row) for row in matrix)
    # Pad shorter rows with None to avoid index errors (they will be ignored)
    padded = [row + [None] * (cols - len(row)) for row in matrix]
    res = []
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1
    while top <= bottom and left <= right:
        # top row
        for j in range(left, right + 1):
            val = padded[top][j]
            if val is not None:
                res.append(val)
        top += 1
        # right column
        for i in range(top, bottom + 1):
            val = padded[i][right]
            if val is not None:
                res.append(val)
        right -= 1
        if top <= bottom:
            # bottom row
            for j in range(right, left - 1, -1):
                val = padded[bottom][j]
                if val is not None:
                    res.append(val)
            bottom -= 1
        if left <= right:
            # left column
            for i in range(bottom, top - 1, -1):
                val = padded[i][left]
                if val is not None:
                    res.append(val)
            left += 1
    return res

