def solve(s):
    # Accept strings, bytes, or any iterable of characters.
    # Convert to string representation for each element.
    if not s:
        return []
    # If s is bytes, decode to str preserving characters.
    if isinstance(s, (bytes, bytearray)):
        s = s.decode()
    # If it's not a string, treat it as iterable and join its elements as strings.
    if not isinstance(s, str):
        s = ''.join(str(ch) for ch in s)
    res = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = ch
            count = 1
    res.append([prev, count])
    return res

