    if not tokens:
        return 0

    def div(a, b):
        q = abs(a) // abs(b)
        return q if (a >= 0) == (b >= 0) else -q

    ops = {'+': lambda a, b: a + b,
           '-': lambda a, b: a - b,
           '*': lambda a, b: a * b,
           '/': div}
    stack = []
    for tok in tokens:
        tok = tok.strip() if isinstance(tok, str) else tok
        if tok == '' or tok is None:
            continue
        if isinstance(tok, str) and tok in ops:
            b = stack.pop()
            a = stack.pop()
            stack.append(ops[tok](a, b))
        else:
            stack.append(int(tok))
    return stack[0]
